WITH output AS (SELECT OrderID,OrderItem,InvoiceNo,PaymentMethod,PaymentChannel,Period FROM `pacific-plating-282708.sap_view.RCB_Motor_process_3_change`), charge_keys AS (SELECT c.id,c.transaction_id,c.third_party_id,c.payment_method,c.service_provider FROM `pacific-plating-282708.careos.carepay_charges` c WHERE c.status='SUCCESSFUL'), matched AS (SELECT v.OrderID,v.OrderItem,v.InvoiceNo,v.PaymentMethod,v.PaymentChannel,c.id charge_id,c.payment_method source_method,c.service_provider source_provider,t.payment_option FROM output v LEFT JOIN `pacific-plating-282708.careos.careos_orders` o ON o.human_id=v.OrderID LEFT JOIN `pacific-plating-282708.careos.carepay_transactions` t ON CONCAT('transactions/',t.id)=o.payment LEFT JOIN charge_keys c ON c.transaction_id=t.id AND c.third_party_id=v.InvoiceNo) SELECT CURRENT_TIMESTAMP() checked_at_utc,source_method,source_provider,payment_option,PaymentMethod output_method,PaymentChannel output_channel,COUNT(*) matched_output_rows,COUNT(DISTINCT charge_id) matched_charges,COUNT(DISTINCT OrderItem) items,COUNTIF(charge_id IS NULL) unmatched_rows FROM matched GROUP BY source_method,source_provider,payment_option,PaymentMethod,PaymentChannel ORDER BY matched_output_rows DESC;